;( function ($, _, undefined) {

    "use strict";

    ips.controller.register( 'reviews.admin.products.products',
    {
        initialize: function () {
            this.on( 'click', '[data-action="toggleProduct"]', this.toggleEnabled );
        },

        toggleEnabled: function( e ) {
            var element = e.target;
            e.preventDefault();

            ips.getAjax()( $( element ).attr( 'href' ),
                {
                    type: 'post',
                    dataType: 'json'
                })
                .done( function( response ){
                    if( response.enabled == 1 )
                    {
                        $( element ).addClass( 'ipsBadge_positive' )
                            .removeClass( 'ipsBadge_negative' )
                            .text( 'Enabled' );
                    }
                    else
                    {
                        $( element ).addClass( 'ipsBadge_negative' )
                            .removeClass( 'ipsBadge_positive' )
                            .text( 'Disabled' );
                    }
                });
        }
    });
}(jQuery, _));
